'use strict';

// MODULES //

var replace = require( '@stdlib/string-replace' );


// MAIN //

/**
* Returns a bounded, single-line-safe error message.
*
* @param {*} error - error-like value
* @param {number} [limit=1000] - maximum message length
* @returns {string} bounded message
*/
function boundedMessage( error, limit ) {
	var value;

	limit = limit || 1000;
	value = ( error instanceof Error ) ? error.message : String( error );
	return replace( value, /[\u0000-\u001f\u007f]/g, ' ' ).slice( 0, limit );
}


// EXPORTS //

module.exports = boundedMessage;
